CREATE TABLE exam_templates(id TEXT PRIMARY KEY,part TEXT NOT NULL CHECK(part IN ('op','simulator')),title TEXT NOT NULL,moments JSONB NOT NULL DEFAULT '[]',position INTEGER NOT NULL,deleted_at BIGINT);
CREATE TABLE student_examinations(student_id TEXT PRIMARY KEY REFERENCES students(id) ON DELETE CASCADE,data JSONB NOT NULL,saved_data JSONB,is_draft BOOLEAN NOT NULL,revision INTEGER NOT NULL,updated_at BIGINT NOT NULL,updated_by TEXT NOT NULL);
ALTER TABLE personnel_student_archives DROP CONSTRAINT personnel_student_archives_kind_check;
ALTER TABLE personnel_student_archives ADD CONSTRAINT personnel_student_archives_kind_check CHECK(kind IN ('student','KP1','KP2','Examen'));
INSERT INTO exam_templates(id,part,title,moments,position)
SELECT 'op','op','Operativ',COALESCE(jsonb_agg(jsonb_build_object('id','exam-'||id,'kind','op','title',title,'description',description,'position',position,'children','[]'::jsonb) ORDER BY position,id),'[]'::jsonb),0 FROM iu_moments WHERE kind='op' AND deleted_at IS NULL;
